  function capitalize(s) {
    return s ? s.charAt(0).toUpperCase() + s.slice(1) : s;
  }

  function isTitleCase(s) {
    return /^[A-Z][a-z]/.test(s);
  }

  function toTitleCase(s) {
    return s ? s.charAt(0).toUpperCase() + s.slice(1) : s;
  }

